    r.qact = (act + 2 * p.B * p.logits * m.d + scAct) * o.ba;
    const ioHead = p.B * p.logits * (m.d * o.ba + p.lambda * m.V * o.bl);
    r.qio = N * m.d * o.bwOther + ioHead;

    // Bytes by class. KV reads may be repeated (rkv); writes are not.
    for (const c of ['attnG', 'attnW', 'attnS', 'index']) cls[c].Q = kv[c].r * o.rkv * o.bkv + kv[c].w * o.bkv;
    cls.dense.Q = wDense * o.bw + (wDenseOther + normW) * o.bwOther + act * o.ba + N * m.d * o.bwOther;
    cls.expert.Q = wExpert * o.bw;
    cls.head.F = r.fhead + r.fsc;
    cls.head.Q = wHead * o.bwOther + (2 * p.B * p.logits * m.d + scAct) * o.ba + ioHead;
    r.cls = cls;

    r.F = r.flin + r.fatt + r.fhead + r.fsc;
    r.Q = r.qw + r.qkvr + r.qkvw + r.qact + r.qio;
    r.AI = r.F / r.Q;
